const cookie = require('/work/index.js');

const CONTROL_PAYLOAD = 'mode';
const EXPLOIT_PAYLOAD = 'mode; Secure';

function run_target(payload) {
  try {
    const observed = cookie.serialize(payload, 'owned');
    return typeof observed === 'string'
      && observed === `${payload}=owned`
      && !observed.includes(';');
  } catch (error) {
    if (error instanceof TypeError && error.message === 'argument name is invalid') return true;
    throw error;
  }
}

module.exports = { CONTROL_PAYLOAD, EXPLOIT_PAYLOAD, run_target };
